// ─── Roles & Permissions ──────────────────────────────────────────────────────

async function seedRolesAndPermissions() {
  const permissions = [
    { action: 'manage', subject: 'all', description: 'Full access to everything' },
    { action: 'create', subject: 'Tool', description: 'Create AI tools' },
    { action: 'read',   subject: 'Tool', description: 'Read AI tools' },
    { action: 'update', subject: 'Tool', description: 'Update AI tools' },
    { action: 'delete', subject: 'Tool', description: 'Delete AI tools' },
    { action: 'create', subject: 'Category', description: 'Create categories' },
    { action: 'update', subject: 'Category', description: 'Update categories' },
    { action: 'delete', subject: 'Category', description: 'Delete categories' },
    { action: 'read',   subject: 'User', description: 'Read user data' },
    { action: 'update', subject: 'User', description: 'Update user data' },
    { action: 'delete', subject: 'User', description: 'Delete users' },
    { action: 'manage', subject: 'Subscription', description: 'Manage subscriptions' },
    { action: 'manage', subject: 'Credits', description: 'Manage credits' },
    { action: 'read',   subject: 'AdminLog', description: 'Read audit logs' },
  ];
  for (const perm of permissions) {
    await prisma.permission.upsert({ where: { action_subject: { action: perm.action, subject: perm.subject } }, update: { description: perm.description }, create: perm });
  }
  const adminRole = await prisma.role.upsert({ where: { name: 'admin' }, update: { description: 'Full platform administrator', isSystem: true }, create: { name: 'admin', description: 'Full platform administrator', isSystem: true } });
  const userRole  = await prisma.role.upsert({ where: { name: 'user'  }, update: { description: 'Standard authenticated user',  isSystem: true }, create: { name: 'user',  description: 'Standard authenticated user',  isSystem: true } });
  const manageAll = await prisma.permission.findUnique({ where: { action_subject: { action: 'manage', subject: 'all'  } } });
  const readTool  = await prisma.permission.findUnique({ where: { action_subject: { action: 'read',   subject: 'Tool' } } });
  if (manageAll) await prisma.rolePermission.upsert({ where: { roleId_permissionId: { roleId: adminRole.id, permissionId: manageAll.id } }, update: {}, create: { roleId: adminRole.id, permissionId: manageAll.id } });
  if (readTool)  await prisma.rolePermission.upsert({ where: { roleId_permissionId: { roleId: userRole.id,  permissionId: readTool.id  } }, update: {}, create: { roleId: userRole.id,  permissionId: readTool.id  } });
  console.log('  ✓ Roles & permissions seeded');
}

