// ─── Tool type ────────────────────────────────────────────────────────────────

type ToolSeed = {
  name: string; slug: string; description: string; shortDescription: string;
  categorySlug: string; tags: string[]; isPremium: boolean; isFeatured: boolean; sortOrder: number;
  config: { systemPrompt: string; userPromptTemplate: string; inputSchema: object; outputFormat: string; aiModel: string; maxTokens: number; temperature: number; creditCost: number };
};

// ─── AI Tools ─────────────────────────────────────────────────────────────────

async function seedTools() {
  const categoryMap = await prisma.category.findMany().then(cats => Object.fromEntries(cats.map(c => [c.slug, c.id])));
  const tools: ToolSeed[] = [...writingTools(), ...marketingTools(), ...seoTools(), ...socialTools(), ...imageTools(), ...codeExtendedTools(), ...productivityTools(), ...otherTools()];

  for (const tool of tools) {
    const categoryId = categoryMap[tool.categorySlug];
    if (!categoryId) { console.warn(`  ⚠ Category not found: ${tool.categorySlug}`); continue; }
    const created = await prisma.aITool.upsert({
      where: { slug: tool.slug },
      update: { name: tool.name, description: tool.description, shortDescription: tool.shortDescription, categoryId, tags: tool.tags, isPremium: tool.isPremium, isFeatured: tool.isFeatured, sortOrder: tool.sortOrder },
      create: { name: tool.name, slug: tool.slug, description: tool.description, shortDescription: tool.shortDescription, categoryId, tags: tool.tags, isPremium: tool.isPremium, isFeatured: tool.isFeatured, sortOrder: tool.sortOrder },
    });
    await prisma.toolConfiguration.upsert({
      where: { toolId: created.id },
      update: { ...tool.config },
      create: { toolId: created.id, ...tool.config },
    });
  }
  console.log(`  ✓ ${tools.length} AI tools seeded`);
}

