// ─── Admin User ───────────────────────────────────────────────────────────────

async function seedAdminUser() {
  const email = 'admin@crackncode.ai';
  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) { console.log('  ✓ Admin user already exists, skipping'); return; }

  const passwordHash = await bcrypt.hash('Admin@123456', 12);
  const adminRole = await prisma.role.findUnique({ where: { name: 'admin' } });
  const freePlan  = await prisma.plan.findUnique({ where: { tier: 'free' } });

  const admin = await prisma.user.create({
    data: {
      email, passwordHash, role: 'admin', isEmailVerified: true,
      profile:       { create: { name: 'CracknCode Admin', timezone: 'UTC', locale: 'en' } },
      creditAccount: { create: { balance: 9999 } },
      subscription:  freePlan ? { create: { planId: freePlan.id, status: 'active' } } : undefined,
    },
  });

  if (adminRole) {
    await prisma.userRoleAssignment.create({ data: { userId: admin.id, roleId: adminRole.id } });
  }

  console.log(`  ✓ Admin user created: ${email} / Admin@123456`);
  console.log('  ⚠  Change the admin password immediately after first login!');
}

// ─── Run ──────────────────────────────────────────────────────────────────────

main()
  .catch((e) => { console.error('❌ Seed failed:', e); process.exit(1); })
  .finally(() => prisma.$disconnect());
